import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Plus, PanelLeft } from 'lucide-react'
import { useSidebar } from '@/contexts/SidebarContext'
import { CollectionHeader } from './CollectionHeader'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface EmptyStateConfig {
  icon: ReactNode
  title: string
  description: string
  noItemsTitle?: string
  noItemsDescription?: string
  showAddButton?: boolean
  addButtonText?: string
}

interface CollectionPageProps<TItem> {
  // Core data
  items: TItem[]
  filteredItems: TItem[]
  loading: boolean

  // Header configuration
  title: string
  subtitle?: string

  // Search and filtering
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
    mobileFilterOptions?: FilterOption[]
  }


  // View mode support (optional)
  viewMode?: {
    current: string
    onChange: (mode: string) => void
    component: ReactNode
  }

  // Secondary controls (optional)
  secondaryControls?: ReactNode


  // Empty states
  emptyState: EmptyStateConfig

  // Item rendering
  renderItems: (items: TItem[], viewMode?: string) => ReactNode

  // Action handlers
  onAdd?: () => void

  // Modal slots
  renderModals?: () => ReactNode

  // Floating action button
  showFloatingActionButton?: boolean

  // Custom loading skeleton
  renderLoadingSkeleton?: () => ReactNode
}

export function CollectionPage<TItem>({
  items,
  filteredItems,
  loading,
  title,
  subtitle,
  searchTerm,
  onSearchChange,
  searchPlaceholder,
  primaryFilter,
  viewMode,
  secondaryControls,
  emptyState,
  renderItems,
  onAdd,
  renderModals,
  showFloatingActionButton = false,
  renderLoadingSkeleton
}: CollectionPageProps<TItem>) {
  const { toggleSidebar } = useSidebar()

  const hasNoItems = items.length === 0
  const hasNoFilteredItems = filteredItems.length === 0
  const isFiltered = searchTerm || primaryFilter?.selectedValue

  const defaultLoadingSkeleton = () => (
    <div className="space-y-4">
      {[...Array(5)].map((_, i) => (
        <Skeleton key={i} className="h-16 w-full" />
      ))}
    </div>
  )

  return (
    <div className="min-h-[calc(100vh-4rem)] lg:min-h-screen">
      <div className="container mx-auto px-4 py-6 sm:py-8">
        {/* Page Header */}
        <div className="mb-6 sm:mb-8">
          <div className="flex items-start gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={toggleSidebar}
              className="hidden lg:flex mt-1 h-8 w-8 hover:bg-accent rounded-md flex-shrink-0"
              aria-label="Toggle sidebar"
            >
              <PanelLeft className="h-4 w-4" />
            </Button>
            <div className="flex-1">
              <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">{title}</h1>
              {subtitle && (
                <p className="text-muted-foreground mt-1 text-sm sm:text-base">
                  {subtitle}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Collection Header */}
        <CollectionHeader
          searchTerm={searchTerm}
          onSearchChange={onSearchChange}
          searchPlaceholder={searchPlaceholder}
          primaryFilter={primaryFilter}
          secondaryControls={
            <>
              {viewMode && viewMode.component}
              {secondaryControls}
            </>
          }
          mobileFilterOptions={primaryFilter?.mobileFilterOptions}
        />

        {/* Main Content */}
        <div className="mt-6">
          {loading ? (
            renderLoadingSkeleton ? renderLoadingSkeleton() : defaultLoadingSkeleton()
          ) : hasNoItems ? (
            /* Empty state - no items at all */
            <Card className="p-12 text-center">
              {emptyState.icon}
              <h3 className="text-lg font-medium mb-2">
                {emptyState.noItemsTitle || emptyState.title}
              </h3>
              <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
                {emptyState.noItemsDescription || emptyState.description}
              </p>
              {emptyState.showAddButton && onAdd && (
                <Button
                  onClick={onAdd}
                  className="min-h-[44px]"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  {emptyState.addButtonText || 'Add First Item'}
                </Button>
              )}
            </Card>
          ) : hasNoFilteredItems && isFiltered ? (
            /* Empty state - no results after filtering */
            <Card className="p-12 text-center">
              {emptyState.icon}
              <h3 className="text-lg font-medium mb-2">
                {emptyState.title}
              </h3>
              <p className="text-sm text-muted-foreground">
                {emptyState.description}
              </p>
            </Card>
          ) : (
            /* Render items */
            renderItems(filteredItems, viewMode?.current)
          )}
        </div>
      </div>

      {/* Floating Action Button */}
      {showFloatingActionButton && onAdd && (
        <div className="fixed bottom-20 lg:bottom-6 right-4 sm:right-6 lg:right-8 z-50">
          <Button
            size="lg"
            className="rounded-full shadow-lg h-14 w-14 p-0 bg-primary hover:bg-primary/90"
            onClick={onAdd}
            aria-label="Add new item"
          >
            <Plus className="h-6 w-6" />
          </Button>
        </div>
      )}

      {/* Modals */}
      {renderModals?.()}
    </div>
  )
}

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Search, Filter, ChevronDown } from 'lucide-react'
import { FilterDropdown } from './FilterDropdown'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface CollectionHeaderProps {
  // Search
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary Filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
  }


  // Secondary controls (optional)
  secondaryControls?: React.ReactNode

  // Mobile filter options (if primaryFilter provided)
  mobileFilterOptions?: FilterOption[]

  // Styling
  className?: string
}

export function CollectionHeader({
  searchTerm,
  onSearchChange,
  searchPlaceholder = "Search...",
  primaryFilter,
  secondaryControls,
  mobileFilterOptions,
  className = ""
}: CollectionHeaderProps) {
  const [showMobileFilters, setShowMobileFilters] = useState(false)

  const selectedFilterOption = primaryFilter?.options.find(
    opt => opt.value === primaryFilter.selectedValue
  )

  return (
    <div className={`bg-white border-b border-border/40 sticky top-16 z-40 ${className}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
        <div className="flex flex-col gap-3">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              type="text"
              placeholder={searchPlaceholder}
              value={searchTerm}
              onChange={(e) => onSearchChange(e.target.value)}
              className="pl-10 min-h-[44px]"
            />
          </div>

          {/* Mobile Filter & Controls */}
          {(primaryFilter || secondaryControls) && (
            <div className="flex gap-2 sm:hidden">
              {primaryFilter && (
                <Button
                  variant="outline"
                  className="flex-1 justify-between min-h-[44px]"
                  onClick={() => setShowMobileFilters(!showMobileFilters)}
                >
                  <span className="flex items-center gap-2">
                    <Filter className="h-4 w-4" />
                    {selectedFilterOption?.label || primaryFilter.placeholder || 'All Items'}
                  </span>
                  <ChevronDown className={`h-4 w-4 transition-transform ${showMobileFilters ? 'rotate-180' : ''}`} />
                </Button>
              )}
              {/* Spacer to push secondary controls to the right when no primary filter */}
              {!primaryFilter && <div className="flex-1"></div>}
              {secondaryControls && (
                <div className="flex gap-2">
                  {secondaryControls}
                </div>
              )}
            </div>
          )}

          {/* Desktop Controls Row */}
          {(primaryFilter || secondaryControls) && (
            <div className="hidden sm:flex gap-2 items-center">
              {/* Primary Filter */}
              {primaryFilter && (
                <div className="w-48">
                  <FilterDropdown
                    options={primaryFilter.options}
                    selectedValue={primaryFilter.selectedValue}
                    onSelectValue={primaryFilter.onSelectValue}
                    placeholder={primaryFilter.placeholder}
                    allItemsLabel={primaryFilter.allItemsLabel}
                    totalItems={primaryFilter.totalItems}
                  />
                </div>
              )}

              {/* Spacer */}
              <div className="flex-1"></div>

              {/* Secondary Controls */}
              {secondaryControls && (
                <div className="flex gap-2 items-center">
                  {secondaryControls}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Mobile Filter Grid */}
        {primaryFilter && showMobileFilters && mobileFilterOptions && (
          <div className="mt-3 p-3 bg-muted/50 rounded-lg sm:hidden">
            <div className="grid grid-cols-2 gap-2">
              <Button
                variant={primaryFilter.selectedValue ? 'outline' : 'default'}
                size="sm"
                className="justify-start min-h-[44px]"
                onClick={() => {
                  primaryFilter.onSelectValue(null)
                  setShowMobileFilters(false)
                }}
              >
                {primaryFilter.allItemsLabel || 'All Items'}
              </Button>
              {mobileFilterOptions.map(option => (
                <Button
                  key={option.value}
                  variant={primaryFilter.selectedValue === option.value ? 'default' : 'outline'}
                  size="sm"
                  className="justify-start min-h-[44px]"
                  onClick={() => {
                    primaryFilter.onSelectValue(option.value === primaryFilter.selectedValue ? null : option.value)
                    setShowMobileFilters(false)
                  }}
                >
                  {option.label}
                </Button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

import { ReactNode, useState, useMemo, useCallback } from 'react'
import {
  Table,
  TableBody,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { ChevronUp, ChevronDown, ChevronsUpDown } from 'lucide-react'
import { CollectionTableTotals } from './CollectionTableTotals'

export interface TableColumn<T = any> {
  key: string
  label: string
  sortable?: boolean
  className?: string
  hideOnMobile?: boolean
  sortValue?: (item: T) => string | number
}

export interface CollectionTableProps<T = any> {
  columns: TableColumn<T>[]
  children?: ReactNode
  // Legacy props for backward compatibility
  sortField?: string
  sortDirection?: 'asc' | 'desc'
  onSort?: (field: string) => void
  // New generic sorting props
  items?: T[]
  renderRow?: (item: T, index: number) => ReactNode
  defaultSortField?: string
  className?: string
  // Totals row support
  showTotals?: boolean
  totals?: (string | number | null)[]
}

export function CollectionTable<T = any>({
  columns,
  children,
  sortField: externalSortField,
  sortDirection: externalSortDirection,
  onSort: externalOnSort,
  items,
  renderRow,
  defaultSortField,
  className = '',
  showTotals = false,
  totals = []
}: CollectionTableProps<T>) {
  // Internal sorting state (used when items/renderRow are provided)
  const [internalSortField, setInternalSortField] = useState<string>(defaultSortField || columns.find(c => c.sortable)?.key || '')
  const [internalSortDirection, setInternalSortDirection] = useState<'asc' | 'desc'>('asc')

  // Internal sort handler - always create the callback
  const internalOnSort = useCallback((field: string) => {
    if (internalSortField === field) {
      setInternalSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setInternalSortField(field)
      setInternalSortDirection('asc')
    }
  }, [internalSortField])

  // Use external sort state if provided, otherwise use internal
  const sortField = externalSortField ?? internalSortField
  const sortDirection = externalSortDirection ?? internalSortDirection
  const onSort = externalOnSort ?? internalOnSort

  // Sort items if provided
  const sortedItems = useMemo(() => {
    if (!items || !sortField) return items

    const sortColumn = columns.find(c => c.key === sortField)
    if (!sortColumn?.sortable) return items

    return [...items].sort((a, b) => {
      let aValue: string | number
      let bValue: string | number

      if (sortColumn.sortValue) {
        aValue = sortColumn.sortValue(a)
        bValue = sortColumn.sortValue(b)
      } else {
        // Default: try to get the value by key
        aValue = (a as any)[sortField] ?? ''
        bValue = (b as any)[sortField] ?? ''
      }

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle number comparison
      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortDirection === 'asc'
          ? aValue - bValue
          : bValue - aValue
      }

      // Mixed types - convert to string for comparison
      const aStr = String(aValue)
      const bStr = String(bValue)
      return sortDirection === 'asc'
        ? aStr.localeCompare(bStr)
        : bStr.localeCompare(aStr)
    })
  }, [items, sortField, sortDirection, columns])

  const getSortIcon = (columnKey: string) => {
    if (sortField !== columnKey) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc' 
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className={`bg-white rounded-lg border border-border/40 overflow-hidden ${className}`}>
      <Table>
        <TableHeader>
          <TableRow className="h-10">
            {columns.map((column) => (
              <TableHead
                key={column.key}
                className={`text-sm font-medium ${
                  column.sortable ? 'cursor-pointer hover:bg-accent/50' : ''
                } ${column.hideOnMobile ? 'hidden sm:table-cell' : ''} ${column.className || ''}`}
                onClick={() => column.sortable && onSort?.(column.key)}
              >
                <div className={`flex items-center ${column.className?.includes('text-right') ? 'justify-end' : ''}`}>
                  {column.label}
                  {column.sortable && getSortIcon(column.key)}
                </div>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {children || (sortedItems && renderRow ? sortedItems.map(renderRow) : null)}
          {showTotals && items && (
            <CollectionTableTotals
              itemCount={items.length}
              totals={totals}
              columnCount={columns.length}
            />
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { lazy, Suspense } from 'react'
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom'
import { QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { AuthProvider, useAuth } from './contexts/AuthContext'
import { SidebarProvider } from './contexts/SidebarContext'
import { ProtectedRoute } from './components/auth/ProtectedRoute'
import { AppLayout } from './components/layout/AppLayout'
import { Toaster } from './components/ui/toaster'
import { Skeleton } from './components/ui/skeleton'
import { queryClient } from './lib/queryClient'
import './App.css'

// Lazy load heavy pages for code splitting
const LoginForm = lazy(() => import('./components/auth/LoginForm').then(m => ({ default: m.LoginForm })))
const SignupForm = lazy(() => import('./components/auth/SignupForm').then(m => ({ default: m.SignupForm })))
const Dashboard = lazy(() => import('./pages/Dashboard').then(m => ({ default: m.Dashboard })))
const GearPage = lazy(() => import('./pages/GearPage').then(m => ({ default: m.GearPage })))
const ListsPage = lazy(() => import('./pages/ListsPage').then(m => ({ default: m.ListsPage })))
const ProfilePage = lazy(() => import('./pages/ProfilePage').then(m => ({ default: m.ProfilePage })))
const SettingsPage = lazy(() => import('./pages/SettingsPage').then(m => ({ default: m.SettingsPage })))

// Loading fallback component
function PageLoader() {
  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="space-y-4 w-full max-w-md">
        <Skeleton className="h-12 w-3/4 mx-auto" />
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-8 w-1/2 mx-auto" />
      </div>
    </div>
  )
}

function AppRoutes() {
  const { user } = useAuth()

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {/* Public routes */}
        <Route 
          path="/login" 
          element={user ? <Navigate to="/" /> : <LoginForm />} 
        />
        <Route 
          path="/signup" 
          element={user ? <Navigate to="/" /> : <SignupForm />} 
        />

        {/* Protected routes wrapped in AppLayout */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Dashboard />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        {/* Keep /dashboard as alias for backwards compatibility */}
        <Route
          path="/dashboard"
          element={<Navigate to="/" replace />}
        />
        <Route
          path="/gear"
          element={
            <ProtectedRoute>
              <AppLayout>
                <GearPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/lists"
          element={
            <ProtectedRoute>
              <AppLayout>
                <ListsPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <ProtectedRoute>
              <AppLayout>
                <ProfilePage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/settings"
          element={
            <ProtectedRoute>
              <AppLayout>
                <SettingsPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
      </Routes>
    </Suspense>
  )
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Router>
        <AuthProvider>
          <SidebarProvider>
            <AppRoutes />
            <Toaster />
          </SidebarProvider>
        </AuthProvider>
      </Router>
      {process.env.NODE_ENV === 'development' && !window.navigator.webdriver && <ReactQueryDevtools initialIsOpen={false} />}
    </QueryClientProvider>
  )
}

export default App

import React, { ReactNode, useState, useEffect } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { UserDropdownMenu } from './UserDropdownMenu'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Mountain, Home, ListTodo, Package, User, ChevronUp, ChevronDown, PanelLeft } from 'lucide-react'
import { useAuth } from '@/contexts/AuthContext'
import { useSidebar } from '@/contexts/SidebarContext'
import { getDisplayNameFromEmail } from '@/utils/user'

interface AppLayoutProps {
  children: ReactNode
}

interface NavItem {
  label: string
  href: string
  icon: React.ComponentType<{ className?: string }>
  mobileOnly?: boolean
  desktopOnly?: boolean
}

const navItems: NavItem[] = [
  { label: 'Home', href: '/', icon: Home },
  { label: 'Lists', href: '/lists', icon: ListTodo },
  { label: 'Gear', href: '/gear', icon: Package },
  { label: 'Profile', href: '/profile', icon: User },
]

export function AppLayout({ children }: AppLayoutProps) {
  const { user, signOut } = useAuth()
  const { isCollapsed: isSidebarCollapsed, toggleSidebar } = useSidebar()
  const location = useLocation()
  const [isMobile, setIsMobile] = useState(false)
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false)

  useEffect(() => {
    const checkMobile = () => {
      // Show mobile nav below lg breakpoint (1024px) to match sidebar visibility
      setIsMobile(window.innerWidth < 1024)
    }

    checkMobile()

    // Debounce resize events for better performance
    let resizeTimer: NodeJS.Timeout
    const handleResize = () => {
      clearTimeout(resizeTimer)
      resizeTimer = setTimeout(checkMobile, 150)
    }

    window.addEventListener('resize', handleResize)
    return () => {
      window.removeEventListener('resize', handleResize)
      clearTimeout(resizeTimer)
    }
  }, [])


  const isActiveRoute = (path: string) => {
    if (path === '/') {
      return location.pathname === '/' || location.pathname === '/dashboard'
    }
    return location.pathname === path || location.pathname.startsWith(path + '/')
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Desktop Sidebar - Hidden on mobile */}
      <aside 
        role="complementary"
        aria-label="Main navigation"
        className={cn(
          "fixed left-0 top-0 z-40 h-screen bg-white border-r border-border/40 transition-all duration-200",
          "hidden lg:block",
          isSidebarCollapsed ? "w-20" : "w-64"
        )}>
        <div className="flex flex-col h-full">
          {/* Logo/Brand */}
          <div className="border-b border-border/40">
            <div className="flex items-center justify-between px-6 py-5">
              <div className={cn(
                "flex items-center",
                isSidebarCollapsed ? "justify-center w-full" : "space-x-3"
              )}>
                <div className="p-2 bg-primary/10 rounded-lg">
                  <Mountain className="h-5 w-5 text-primary" />
                </div>
                {!isSidebarCollapsed && (
                  <span className="text-xl font-semibold">BetterPack</span>
                )}
              </div>
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-4 py-6 space-y-1" aria-label="Primary navigation">
            {navItems.filter(item => !item.mobileOnly).map((item) => {
              const Icon = item.icon
              const isActive = isActiveRoute(item.href)

              if (isSidebarCollapsed) {
                return (
                  <TooltipProvider key={item.href}>
                    <Tooltip delayDuration={0}>
                      <TooltipTrigger asChild>
                        <NavLink
                          to={item.href}
                          className={cn(
                            "flex items-center justify-center px-3 py-2.5 rounded-lg transition-colors duration-150",
                            "hover:bg-accent",
                            isActive && "bg-primary/10 text-primary font-medium"
                          )}
                          aria-current={isActive ? "page" : undefined}
                        >
                          <Icon className="h-5 w-5" />
                        </NavLink>
                      </TooltipTrigger>
                      <TooltipContent side="right" className="font-medium text-sm">
                        <p>{item.label}</p>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                )
              }

              return (
                <NavLink
                  key={item.href}
                  to={item.href}
                  className={cn(
                    "flex items-center space-x-3 px-3 py-2.5 rounded-lg transition-colors duration-150",
                    "hover:bg-accent",
                    isActive && "bg-primary/10 text-primary font-medium"
                  )}
                  aria-current={isActive ? "page" : undefined}
                >
                  <Icon className="h-5 w-5" />
                  <span>{item.label}</span>
                </NavLink>
              )
            })}
          </nav>

          {/* User section with dropdown */}
          <div className="border-t border-border/40 p-3">
            {!isSidebarCollapsed ? (
              <DropdownMenu open={isUserMenuOpen} onOpenChange={setIsUserMenuOpen}>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    className="w-full justify-between px-3 py-2.5 min-h-[44px] h-auto hover:bg-accent cursor-pointer"
                    aria-label="User menu"
                    aria-expanded={isUserMenuOpen}
                    aria-haspopup="true"
                  >
                    <div className="flex items-center space-x-3 min-w-0">
                      <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                        <User className="h-4 w-4 text-primary" />
                      </div>
                      <span className="text-sm font-medium truncate">
                        {user?.email ? getDisplayNameFromEmail(user?.email) : 'User'}
